import csv
import io
import re
from typing import List, Dict, Any


def _split_csv_records(text: str) -> List[str]:
    records: List[str] = []
    buffer: List[str] = []
    in_quotes = False
    at_field_start = True
    i = 0

    while i < len(text):
        ch = text[i]

        if in_quotes:
            buffer.append(ch)
            if ch == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    buffer.append('"')
                    i += 1
                else:
                    in_quotes = False
                    at_field_start = False
        else:
            if ch == '"' and at_field_start:
                in_quotes = True
                buffer.append(ch)
                at_field_start = False
            elif ch == ',':
                buffer.append(ch)
                at_field_start = True
            elif ch == '\r' or ch == '\n':
                records.append("".join(buffer))
                buffer = []
                at_field_start = True
                if ch == '\r' and i + 1 < len(text) and text[i + 1] == '\n':
                    i += 1
            else:
                buffer.append(ch)
                if not ch.isspace():
                    at_field_start = False
        i += 1

    if buffer or (text and text[-1] not in "\r\n"):
        records.append("".join(buffer))

    return records


def _parse_record(record: str) -> List[str]:
    try:
        reader = csv.reader(
            io.StringIO(record, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
        return next(reader, [])
    except csv.Error:
        return record.split(",")


def _normalize_header(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", value.lower().replace("\ufeff", ""))


def _find_header(records: List[str], expected_width: int) -> int:
    known_headers = {
        "date",
        "time",
        "qty",
        "quantity",
        "productid",
        "price",
        "producttype",
        "productdescription",
        "url",
        "comments",
        "comment",
    }

    best_index = -1
    best_score = -1

    for index, record in enumerate(records[:100]):
        row = _parse_record(record)
        if len(row) != expected_width:
            continue

        normalized = [_normalize_header(value) for value in row]
        score = sum(1 for value in normalized if value in known_headers)
        score += len(set(normalized)) // 3
        if normalized and normalized[0] in {"date", "datetime", "transactiondate"}:
            score += 3
        if any(value in {"productid", "productdescription", "url"} for value in normalized):
            score += 2

        if score > best_score:
            best_score = score
            best_index = index

    if best_index >= 0:
        return best_index

    for index, record in enumerate(records):
        if len(_parse_record(record)) == expected_width:
            return index

    return 0


def _is_data_start(record: str) -> bool:
    row = _parse_record(record)
    if not row:
        return False

    value = row[0].strip().strip('"')
    return bool(
        re.match(r"^\d{1,2}[/-]\d{1,2}[/-]\d{2,4}(?:\s|$)", value)
        or re.match(r"^\d{4}[/-]\d{1,2}[/-]\d{1,2}(?:[T\s]|$)", value)
    )


def _combine_record_group(group: List[str]) -> List[str]:
    if not group:
        return []

    fields = _parse_record(group[0])

    for continuation in group[1:]:
        parts = _parse_record(continuation)
        if not parts:
            if fields:
                fields[-1] += "\n"
            continue

        if not fields:
            fields = parts
        else:
            fields[-1] += "\n" + parts[0]
            fields.extend(parts[1:])

    return fields


def _repair_width(
    fields: List[str],
    columns: List[str],
    expected_width: int,
) -> List[str]:
    fields = ["" if value is None else str(value) for value in fields]

    if len(fields) == expected_width:
        return fields

    if len(fields) < expected_width:
        return fields + [""] * (expected_width - len(fields))

    normalized = [_normalize_header(column) for column in columns]

    try:
        description_index = normalized.index("productdescription")
    except ValueError:
        description_index = max(0, expected_width - 3)

    try:
        url_index = normalized.index("url")
    except ValueError:
        url_index = -1

    if url_index > description_index:
        url_field_index = -1
        for index in range(description_index + 1, len(fields)):
            if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", fields[index].strip()):
                url_field_index = index
                break

        if url_field_index >= 0:
            result = fields[:description_index]
            result.append(",".join(fields[description_index:url_field_index]))
            result.append(fields[url_field_index])

            trailing = fields[url_field_index + 1:]
            trailing_columns = expected_width - url_index - 1
            if trailing_columns > 0:
                if trailing_columns == 1:
                    result.append(",".join(trailing))
                else:
                    while len(trailing) > trailing_columns:
                        trailing[-2] = trailing[-2] + "," + trailing[-1]
                        trailing.pop()
                    trailing.extend([""] * (trailing_columns - len(trailing)))
                    result.extend(trailing)

            if len(result) < expected_width:
                result.extend([""] * (expected_width - len(result)))
            return result[:expected_width]

    surplus = len(fields) - expected_width
    end = description_index + surplus + 1
    repaired = (
        fields[:description_index]
        + [",".join(fields[description_index:end])]
        + fields[end:]
    )

    if len(repaired) < expected_width:
        repaired.extend([""] * (expected_width - len(repaired)))
    elif len(repaired) > expected_width:
        repaired = repaired[:expected_width - 1] + [
            ",".join(repaired[expected_width - 1:])
        ]

    return repaired


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    raw_csv = raw_csv.lstrip("\ufeff")
    records = _split_csv_records(raw_csv)
    expected_width = 9

    if not records:
        return {"columns": [], "rows": []}

    header_index = _find_header(records, expected_width)
    columns = _parse_record(records[header_index])

    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[:expected_width]

    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    groups: List[List[str]] = []
    current: List[str] = []

    for record in records[header_index + 1:]:
        if not record.strip():
            if current:
                current.append(record)
            continue

        if _is_data_start(record):
            if current:
                groups.append(current)
            current = [record]
        elif current:
            current.append(record)

    if current:
        groups.append(current)

    rows: List[List[str]] = []
    for group in groups:
        fields = _combine_record_group(group)
        if not fields or not any(value != "" for value in fields):
            continue
        rows.append(_repair_width(fields, columns, expected_width))

    return {"columns": columns, "rows": rows}
